package com.pawsshop.repo; import com.pawsshop.model.Product; import org.springframework.data.jpa.repository.*; import javax.persistence.LockModeType; import java.util.Optional;
public interface ProductRepository extends JpaRepository<Product,Long> { @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select p from Product p where p.id = :id") Optional<Product> lockById(@org.springframework.data.repository.query.Param("id") Long id); }
